import type { VRMHumanBone } from '@pixiv/three-vrm-core/types/humanoid/VRMHumanBone';
import type { VRMHumanBoneName } from '@pixiv/three-vrm-core/types/humanoid/VRMHumanBoneName';
import type { VRMRequiredHumanBoneName } from '@pixiv/three-vrm-core/types/humanoid/VRMRequiredHumanBoneName';
/**
 * A map from {@link VRMHumanBoneName} to {@link VRMHumanBone}.
 */
export type VRMHumanBones = {
    [name in VRMHumanBoneName]?: VRMHumanBone;
} & {
    [name in VRMRequiredHumanBoneName]: VRMHumanBone;
};
